  assert.equal(lineDiscount({ qty: 1, unitPrice: 100, discountPercent: 10 }), 10);

  // 95 cents with 10% discount = 9.5 cents → 10 cents (rounded)
  assert.equal(lineDiscount({ qty: 1, unitPrice: 95, discountPercent: 10 }), 10);

